{
  "verdict": "allow",
  "reasons": [
    "All listed fragments are natural‑language descriptions of interface semantics, JSON schemas, synthetic examples, test scenarios, or bindings to declared URLs and request shapes.",
    "No source code, file paths, internal module or class names, stack traces, secrets, real personal data, or internal hostnames other than the declared integration URLs are present."
