      "path": "/operations",
      "value": {
        "create_shipment": {
          "description": "Create a parcel shipment for a paid Spokes order",
          "direction": "consumer_to_provider",
          "request": {
            "method": "POST",
            "path": "/v1/shipments",
            "headers": {
              "Authorization": {
                "required": true,
                "pattern": "^Bearer .+$"
              },
              "Idempotency-Key": {
                "required": false,
                "pattern": "^.{1,255}$"
              },
              "Content-Type": {
                "required": true,
                "pattern": "^application/json$"
              }
            },
            "body": {
              "$ref": "#/schemas/CreateShipmentRequest"
            }
          },
          "responses": {
            "201": {
              "body": {
                "$ref": "#/schemas/Shipment"
              }
            },
            "400": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            },
            "401": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            },
            "422": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            }
          },
          "stub": {
            "default_status": 201,
            "body": {
              "id": "PCL{{seq}}PL",
              "reference": "{{request.body.reference}}",
              "type": "parcel",
              "status": "CREATED",
              "created_at": "{{now}}"
            },
            "idempotent_on_header": "Idempotency-Key"
          }
        },
        "create_pallet": {
          "description": "Create a pallet shipment for a paid Spokes order",
          "direction": "consumer_to_provider",
          "request": {
            "method": "POST",
            "path": "/v1/pallets",
            "headers": {
              "Authorization": {
                "required": true,
                "pattern": "^Bearer .+$"
              },
              "Idempotency-Key": {
                "required": false,
                "pattern": "^.{1,255}$"
              },
              "Content-Type": {
                "required": true,
                "pattern": "^application/json$"
              }
            },
            "body": {
              "$ref": "#/schemas/CreatePalletRequest"
            }
          },
          "responses": {
            "201": {
              "body": {
                "$ref": "#/schemas/Shipment"
              }
            },
            "400": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            },
            "401": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            },
            "422": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            }
          },
          "stub": {
            "default_status": 201,
            "body": {
              "id": "PAL{{seq}}PL",
              "reference": "{{request.body.reference}}",
              "type": "pallet",
              "status": "CREATED",
              "created_at": "{{now}}"
            },
            "idempotent_on_header": "Idempotency-Key"
          }
        },
        "create_partner": {
          "description": "Sandbox only: create a partner record for Spokes",
          "direction": "consumer_to_provider",
          "request": {
            "method": "POST",
            "path": "/__sandbox/partners",
            "headers": {
              "Content-Type": {
                "required": true,
                "pattern": "^application/json$"
              }
            },
            "body": {
              "$ref": "#/schemas/CreatePartnerRequest"
            }
          },
          "responses": {
            "201": {
              "body": {
                "$ref": "#/schemas/Partner"
              }
            },
            "400": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            }
          },
          "stub": {
            "default_status": 201,
            "body": {
              "id": "prt_{{seq}}",
              "name": "{{request.body.name}}",
              "api_key": "{{request.body.api_key || 'pk_test_' + uuid}}",
              "webhook_url": "{{request.body.webhook_url}}",
              "webhook_secret": "{{request.body.webhook_secret || 'whsec_' + uuid}}",
              "require_idempotency_key": "{{request.body.require_idempotency_key || false}}"
            }
          }
        },
        "advance_shipment": {
          "description": "Sandbox only: advance a shipment to a new status",
          "direction": "consumer_to_provider",
          "request": {
            "method": "POST",
            "path": "/__sandbox/shipments/{{shipment_id}}/advance",
            "headers": {
              "Content-Type": {
                "required": true,
                "pattern": "^application/json$"
              }
            },
            "body": {
              "$ref": "#/schemas/AdvanceShipmentRequest"
            }
          },
          "responses": {
            "200": {
              "body": {
                "$ref": "#/schemas/Shipment"
              }
            },
            "400": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            },
            "404": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            }
          },
          "stub": {
            "default_status": 200,
            "body": {
              "id": "{{shipment_id}}",
              "reference": "ORD-{{seq}}",
              "type": "parcel",
              "status": "{{request.body.to}}",
              "created_at": "{{now}}"
            }
          }
        },
        "advance_shipment_by_reference": {
          "description": "Sandbox only: advance the newest shipment for a reference",
          "direction": "consumer_to_provider",
          "request": {
            "method": "POST",
            "path": "/__sandbox/shipments/by-reference/{{reference}}/advance",
            "headers": {
              "Content-Type": {
                "required": true,
                "pattern": "^application/json$"
              }
            },
            "body": {
              "$ref": "#/schemas/AdvanceShipmentRequest"
            }
          },
          "responses": {
            "200": {
              "body": {
                "$ref": "#/schemas/Shipment"
              }
            },
            "400": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            },
            "404": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            }
          },
          "stub": {
            "default_status": 200,
            "body": {
              "id": "PCL{{seq}}PL",
              "reference": "{{reference}}",
              "type": "parcel",
              "status": "{{request.body.to}}",
              "created_at": "{{now}}"
            }
          }
        },
        "get_charges": {
          "description": "Sandbox only: get charge summary for a reference",
          "direction": "consumer_to_provider",
          "request": {
            "method": "GET",
            "path": "/__sandbox/charges",
            "headers": {}
          },
          "responses": {
            "200": {
              "body": {
                "$ref": "#/schemas/ChargeSummary"
              }
            },
            "400": {
              "body": {
                "$ref": "#/schemas/Error"
              }
            }
          },
          "stub": {
            "default_status": 200,
            "body": {
              "count": "{{seq}}",
              "total_groszy": "{{seq * 1299}}"
            }
          }
        }
      }
    },
    {
      "op": "add",
      "path": "/webhooks",
      "value": {
        "shipment_status_changed": {
          "description": "Parcelly posts shipment status changes to Spokes' configured webhook URL",
          "direction": "provider_to_consumer",
          "request": {
            "method": "POST",
            "url": "${CONSUMER_WEBHOOK_URL}",
            "headers": {
              "X-Parcelly-Signature": {
                "required": true,
                "pattern": "^sha256=[0-9a-f]{64}$"
              },
              "Content-Type": {
                "required": true,
                "pattern": "^application/json$"
              }
            },
            "body": {
              "$ref": "#/schemas/ShipmentStatusChanged"
            }
          },
          "signature": {
            "algorithm": "hmac-sha256",
            "header": "X-Parcelly-Signature",
            "format": "sha256={hex}",
            "over": "raw_body",
            "secret": "webhook_secret"
          },
          "consumer_responses": {
            "valid_signature": 200,
            "invalid_signature": 401
          }
        }
      }
    },
    {
      "op": "add",
      "path": "/semantic_mappings",
      "value": {
        "shipment_status_to_order_status": {
          "CREATED": "paid",
          "COLLECTED": "shipped",
          "IN_TRANSIT": "shipped",
          "DELIVERED": "delivered",
          "RETURNED": "returned",
          "CANCELLED": "cancelled"
        },
        "order_id_to_reference": {
          "description": "Spokes order ID (ORD-<number>) is passed as reference field in shipment creation"
        },
        "idempotency_key_from_order_id": {
          "description": "Spokes should use the order ID as Idempotency-Key when creating shipments"
        }
      }
    },
    {
      "op": "add",
      "path": "/decisions",
      "value": [
        {
          "id": "D1",
          "text": "Who converts Spokes' phone numbers (various formats) to Parcelly's required +48XXXXXXXXX format?",
          "owner": "consumer"
        },
        {
          "id": "D2",
          "text": "Who converts weight from kg (Spokes, 3 decimals) to grams (Parcelly, integer)?",
          "owner": "consumer"
        },
        {
          "id": "D3",
          "text": "Who determines parcel size category (A/B/C) from weight? Parcelly validates size-weight match but requires size in request.",
          "owner": "consumer"
        },
        {
          "id": "D4",
          "text": "Who ensures postcode-city pairs are valid per Polish registry? Parcelly validates and rejects mismatches with 422 POSTCODE_CITY_MISMATCH.",
          "owner": "consumer"
        },
        {
          "id": "D5",
          "text": "Mapping of Parcelly shipment statuses to Spokes order statuses (CREATED→paid, COLLECTED→shipped, IN_TRANSIT→shipped, DELIVERED→delivered, RETURNED→returned, CANCELLED→cancelled). Confirm or adjust.",
          "owner": "consumer"
        },
        {
          "id": "D6",
          "text": "Webhook integration pattern: Parcelly POSTs shipment status changes to Spokes' configured webhook URL. Spokes must implement an endpoint that verifies X-Parcelly-Signature and maps statuses to order updates. Confirm this pattern works for Spokes.",
          "owner": "consumer"
        },
        {
          "id": "D7",
          "text": "Partner credentials: What partner ID, API key, webhook URL, and webhook secret should Parcelly use for Spokes? (Sandbox partner creation can set these.)",
          "owner": "consumer"
        },
        {
          "id": "D8",
          "text": "Idempotency: Spokes should use order ID (ORD-<number>) as Idempotency-Key when creating shipments. Confirm.",
          "owner": "consumer"
        },
        {
          "id": "D9",
          "text": "Parcel vs pallet: Spokes sells bikes (typically <25 kg). Confirm all shipments are parcels (size C for 15-25 kg bikes) or if any pallets needed.",
          "owner": "consumer"
        },
        {
          "id": "D10",
          "text": "Country: All shipments to Poland only (country=PL hardcoded). Confirm.",
          "owner": "consumer"
        }
      ]
    },
