    {
      "op": "add",
      "path": "/operations/create_shipment",
      "value": {
        "description": "Create a new parcel shipment",
        "direction": "consumer_to_provider",
        "request": {
          "method": "POST",
          "path": "/v1/shipments",
          "headers": {
            "Authorization": {
              "required": true,
              "pattern": "^Bearer .+$"
            },
            "Idempotency-Key": {
              "required": false,
              "pattern": "^.{1,255}$"
            }
          },
          "body": {
            "$ref": "#/schemas/CreateShipmentRequest"
          }
        },
        "responses": {
          "201": {
            "body": {
              "$ref": "#/schemas/Shipment"
            }
          },
          "400": {
            "body": {
              "$ref": "#/schemas/Error"
            }
          },
          "401": {
            "body": {
              "$ref": "#/schemas/Error"
            }
          },
          "422": {
            "body": {
              "$ref": "#/schemas/Error"
            }
          }
        },
        "stub": {
          "default_status": 201,
          "body": {
            "id": "shp_{{seq}}",
            "reference": "{{request.body.reference}}",
            "status": "CREATED",
            "parcel": {
              "weight_g": "{{request.body.parcel.weight_g}}",
              "size": "{{request.body.parcel.size}}",
              "tracking_number": "PCL{{seq}}PL"
            },
            "created_at": "{{now}}"
          },
          "idempotent_on_header": "Idempotency-Key"
        }
      }
    },
    {
      "op": "add",
      "path": "/operations/register_webhook",
      "value": {
        "description": "Register or update the webhook endpoint for shipment status notifications",
        "direction": "consumer_to_provider",
        "request": {
          "method": "POST",
          "path": "/v1/webhooks",
          "headers": {
            "Authorization": {
              "required": true,
              "pattern": "^Bearer .+$"
            }
          },
          "body": {
            "$ref": "#/schemas/RegisterWebhookRequest"
          }
        },
        "responses": {
          "200": {
            "body": {
              "$ref": "#/schemas/WebhookRegistration"
            }
          },
          "400": {
            "body": {
              "$ref": "#/schemas/Error"
            }
          },
          "401": {
            "body": {
              "$ref": "#/schemas/Error"
            }
          }
        },
        "stub": {
          "default_status": 200,
          "body": {
            "id": "wh_{{seq}}",
            "url": "{{request.body.url}}",
            "secret": "{{secrets.webhook_secret}}"
          }
        }
      }
    },
    {
      "op": "add",
      "path": "/webhooks/shipment_status_changed",
      "value": {
        "description": "Sent when a shipment changes status (CREATED → COLLECTED → IN_TRANSIT → DELIVERED/RETURNED)",
        "direction": "provider_to_consumer",
        "request": {
          "method": "POST",
          "url": "${CONSUMER_WEBHOOK_URL}",
          "headers": {
            "X-Parcelly-Signature": {
              "required": true,
              "pattern": "^sha256=[0-9a-f]{64}$"
            }
          },
          "body": {
            "$ref": "#/schemas/ShipmentStatusChanged"
          }
        },
        "signature": {
          "algorithm": "hmac-sha256",
          "header": "X-Parcelly-Signature",
          "format": "sha256={hex}",
          "over": "raw_body",
          "secret": "webhook_secret"
        },
        "consumer_responses": {
          "valid_signature": 200,
          "invalid_signature": 401
        }
      }
    },
    {
      "op": "add",
      "path": "/semantic_mappings",
      "value": {
        "shipment_status_to_order_status": {
          "CREATED": "paid",
          "COLLECTED": "shipped",
          "IN_TRANSIT": "shipped",
          "DELIVERED": "delivered",
          "RETURNED": "cancelled"
        },
        "phone_format_conversion": {
          "consumer_format": "various (e.g., '600 100 200', '+48600100200', '0048 600-100-200')",
          "provider_format": "+48XXXXXXXXX (E.164, 9 digits after +48)"
        },
        "weight_conversion": {
          "consumer_unit": "kg (e.g., 2.500)",
          "provider_unit": "grams (e.g., 2500)",
          "conversion": "multiply by 1000"
        },
        "address_parsing": {
          "consumer_format": "single line (e.g., 'ul. Długa 5/3, 00-001 Warszawa')",
          "provider_fields": "address_line, postcode (NN-NNN), city, country (PL)"
        }
      }
