    {
      "op": "add",
      "path": "/decisions",
      "value": [
        {
          "id": "D1",
          "text": "Consumer converts phone numbers to E.164 format +48XXXXXXXXX before sending to Parcelly.",
          "owner": "consumer"
        },
        {
          "id": "D2",
          "text": "Consumer parses single-line address into structured fields (address_line, postcode NN-NNN, city, country=PL).",
          "owner": "consumer"
        },
        {
          "id": "D3",
          "text": "Consumer converts weight from kg to grams (multiply by 1000) and selects correct size (A ≤5000g, B 5001-15000g, C 15001-25000g).",
          "owner": "consumer"
        },
        {
          "id": "D4",
          "text": "Consumer uses their Order ID (e.g., ORD-1001) as both the shipment reference and the Idempotency-Key header.",
          "owner": "consumer"
        },
        {
          "id": "D5",
          "text": "Provider validates requests in strict order: schema → phone format → postcode format → weight limit → size/weight match → postcode/city match. Unknown fields cause 400 INVALID_REQUEST.",
          "owner": "provider"
        },
        {
          "id": "D6",
          "text": "Provider returns 400 INVALID_IDEMPOTENCY_KEY for Idempotency-Key headers longer than 255 characters.",
          "owner": "provider"
        },
        {
          "id": "D7",
          "text": "Provider treats blank/whitespace-only Idempotency-Key as absent (no deduplication).",
          "owner": "provider"
        },
        {
          "id": "D8",
          "text": "Provider does not store idempotency keys for 4xx responses, allowing retry with same key after fixing payload.",
          "owner": "provider"
        },
        {
          "id": "D9",
          "text": "Provider signs webhooks with HMAC-SHA256 over raw body, puts signature in X-Parcelly-Signature header as 'sha256=<hex>', using webhook_secret.",
          "owner": "provider"
        },
        {
          "id": "D10",
          "text": "Provider retries webhook delivery up to 5 times with delays 0.5s, 1s, 2s, 4s, 8s; gives up after last failure.",
          "owner": "provider"
        },
        {
          "id": "D11",
          "text": "Consumer verifies webhook signature using webhook_secret and raw request body before processing.",
          "owner": "consumer"
        },
        {
          "id": "D12",
          "text": "Shipment statuses map to Spokes order statuses as: CREATED→paid, COLLECTED→shipped, IN_TRANSIT→shipped, DELIVERED→delivered, RETURNED→cancelled.",
          "owner": "consumer"
        }
      ]
    },
